import assert from 'node:assert/strict';
import fs from 'node:fs';
import {fileURLToPath} from 'node:url';
import {spawn} from 'node:child_process';
import {finished} from 'node:stream/promises';
import {hash,json} from './seal-simple-website-successor.mjs';
import {memoryGate} from './native-website-integration-stage-20261025.mjs';
export async function runBoundWebsiteTests({sourceFile,sourceSha256,evidenceDir,roots,heapMiB=256,memoryMiB=4096,environment={},expectedCases,proof={}}){
 const memory=memoryGate(memoryMiB);assert.equal(hash(sourceFile),sourceSha256);const source=json(sourceFile),site=source.website,indexFile=fileURLToPath(new URL('./CURRENT_CHECKPOINT.json',import.meta.url)),index=json(indexFile);assert.deepEqual(index.activeWork.current.activeExecutionSessions,[]);assert.equal(index.activeWork.current.ownerPreviewPolicy.restartPermitted,false);assert(roots.length>0&&new Set(roots).size===roots.length);assert(roots.every(p=>/^tests\/[a-zA-Z0-9-]+\.test\.(?:mjs|ts)$/.test(p)));
 const verify=()=>{assert.equal(hash(sourceFile),sourceSha256);for(const row of source.sourceRows)assert.equal(hash(site+'/'+row.path),row.sha256,row.path);for(const row of source.dependencies){assert.equal(hash(row.file),row.sha256);assert.equal(hash(row.entry),row.entrySha256);}};verify();assert(!fs.existsSync(evidenceDir));fs.mkdirSync(evidenceDir,{recursive:true});const save=(p,v)=>fs.writeFileSync(evidenceDir+'/'+p,JSON.stringify(v,null,2)+'\n',{flag:'wx'}),args=['--max-old-space-size='+heapMiB,'--experimental-strip-types','--test','--test-concurrency=1','--test-reporter=tap',...roots];
 const child=spawn(process.execPath,args,{cwd:site,windowsHide:true,stdio:['ignore','pipe','pipe'],env:{...process.env,...environment,NODE_OPTIONS:'--max-old-space-size='+heapMiB,GOMEMLIMIT:'64MiB',GOMAXPROCS:'1',RAYON_NUM_THREADS:'1',WRANGLER_SEND_METRICS:'false'}}),out=fs.createWriteStream(evidenceDir+'/stdout.tap',{flags:'wx'}),err=fs.createWriteStream(evidenceDir+'/stderr.log',{flags:'wx'});child.stdout.pipe(out);child.stderr.pipe(err);
 function active(live){const p=json(indexFile);assert.deepEqual(p.goal,index.goal);assert.deepEqual(p.safety,index.safety);assert.deepEqual(p.activeWork.current.ownerPreviewPolicy,index.activeWork.current.ownerPreviewPolicy);p.activeWork.current.activeExecutionSessions=live?[{role:'bound-website-check',pid:child.pid,driverPid:process.pid,evidence:evidenceDir,sourceSha256,previewChanged:false}]:p.activeWork.current.activeExecutionSessions.filter(s=>s.role!=='bound-website-check');const b=Buffer.from(JSON.stringify(p,null,2)+'\n');assert(b.length<65536);fs.writeFileSync(indexFile,b);}
 const done=new Promise((resolve,reject)=>{child.once('error',reject);child.once('close',(exitCode,signal)=>resolve({exitCode,signal}));});await new Promise((resolve,reject)=>{child.once('spawn',resolve);child.once('error',reject);});active(true);save('STARTED.json',{at:new Date().toISOString(),memory,pid:child.pid,driverPid:process.pid,args,sourceSha256,sourcePaths:source.sourceRows.length,environmentKeys:Object.keys(environment),wholeRoots:true,noTestNameFiltering:true});console.log(JSON.stringify({started:true,pid:child.pid,roots:roots.length}));let terminal=false;
 try{const result=await done;terminal=true;await Promise.all([finished(out),finished(err)]);active(false);verify();const tap=fs.readFileSync(evidenceDir+'/stdout.tap','utf8'),counts={};for(const k of ['tests','pass','fail','cancelled','skipped','todo']){const m=tap.match(new RegExp('^# '+k+' (\\d+)\\r?$','m'));counts[k]=m?Number(m[1]):null;}const passing=result.exitCode===0&&!result.signal&&counts.tests>=roots.length&&counts.pass===counts.tests&&(expectedCases===undefined||counts.tests===expectedCases)&&['fail','cancelled','skipped','todo'].every(k=>counts[k]===0);save('TERMINAL.json',{at:new Date().toISOString(),...result,passing,counts,roots:roots.length,sourceSha256,sourcePaths:source.sourceRows.length,sourceAndDependencyDrift:false,stdoutSha256:hash(evidenceDir+'/stdout.tap'),stderrSha256:hash(evidenceDir+'/stderr.log'),scope:proof,wholeSuitePassing:false,clinicalApproval:false,previewChanged:false});console.log(JSON.stringify({passing,...result,counts,roots:roots.length}));return {passing,...result,counts};}catch(e){if(terminal)active(false);save('FAILURE.json',{at:new Date().toISOString(),message:e.message,stack:e.stack,terminal,pid:child.pid});throw e;}
}
